size_t hash1 = ckh->hash(searchkey, 0);
    size_t hash2 = ckh->hash(searchkey, 1);

    // Calculate primary and secondary bucket indices
    size_t bucket_count = (1U << ckh->lg_curbuckets);
    size_t bucket1 = hash1 & (bucket_count - 1);
    size_t bucket2 = hash2 & (bucket_count - 1);

    // Check primary bucket
    for (size_t i = 0; i < (1U << LG_CKH_BUCKET_CELLS); i++) {
        size_t index = ckh_cell_index(bucket1, i);
        if (ckh->tab[index].key != nullptr && ckh->keycomp(ckh->tab[index].key, searchkey)) {
            if (key) *key = const_cast<void*>(ckh->tab[index].key);
            if (data) *data = const_cast<void*>(ckh->tab[index].data);
            return false; // Found
        }
    }

    // Check secondary bucket
    for (size_t i = 0; i < (1U << LG_CKH_BUCKET_CELLS); i++) {
        size_t index = ckh_cell_index(bucket2, i);
        if (ckh->tab[index].key != nullptr && ckh->keycomp(ckh->tab[index].key, searchkey)) {
            if (key) *key = const_cast<void*>(ckh->tab[index].key);
            if (data) *data = const_cast<void*>(ckh->tab[index].data);
            return false; // Found
        }
    }

    // Not found
    if (key) *key = nullptr;
    if (data) *data = nullptr;
    return true;

